B='022尽头.txt'
make('zhang_da','章达',B,
'章达是卫斯理童年结义的朋友，十一岁随任外交官的父亲远行，成年后成为社会心理学研究者，在联合国机构任职并主持国际学术会议。他的成就没有完全磨去孩童般的顽皮：重逢时，他溜出官方接待，打电话告知要自由活动三日，又用旧绰号与朋友说笑。面对暴力与破坏，他却能立刻转回严肃研究，宁愿放弃游玩也要放映自己和学生在各地取得的纪录影片。他曾混入青年群体观察，认为疯狂行动不能简单归因于教育不足；受教育者和失学者都可能作出类似行为，使他怀疑存在影响人的外来因素。这个判断尚在整理和联合研究中，他没有直接掌握控制他人的技术。正当他准备向朋友说出进一步想法时，丁阿毛从窗外开枪将他杀死。最初看似凶手报复卫斯理时误中他，后来证词揭示这是一场被安排成意外的谋杀。章达留下的文稿又被换去，好友李逊失踪，使其工作成为整条追查线的中心。综合终局参战应保留他重视田野材料与人性问题的热情，也保留学术发现可能招致针对的警觉，不能把受害结局换成全知或精神免疫。',
'调查外来控制因素期间被丁阿毛枪杀，研究文稿被偷换。','社会心理研究与田野观察','通过参与观察、影片和合作研究比较社会行为，发现异常影响的线索。','研究结论需要材料；没有直接控制脑电波或抵御枪弹的能力。有关神秘力量的具体认识不能超出所留证据。',[(124,150,'背景与重逢'),(179,222,'影片、研究方法与未说完的结论'),(224,263,'遇害'),(934,949,'谋杀伪装成误杀')],
'找到人类集体破坏行为的原因，同时珍惜私人友情与自由。',[('别人用单一标签解释暴力','手头已有相反样本','展示可比较资料并提出更细的问题。'),('朋友邀他共同研究','问题确实触及长期课题','愿意调整休闲安排投入讨论。'),('敏感发现将被公开','已有被针对的迹象','分散保存证据并寻找可信同行，不独自承担全部风险。')],dead=True,scores=(1,0,1,2,1,1),tier='并',aliases=('章达博士','癞带蛄子'))
make('li_xun','李逊',B,
'李逊是一位带北欧口音的博士，与章达既有深厚友谊，也有共同的社会心理研究。他并非只在文稿封面上留下姓名的人：章达死后，他主动通过长途电话寻找卫斯理，希望继续追查那种影响行为的神秘力量，谈话中的沉痛显出失去伙伴和研究中断的双重打击。他与学生讨论问题时因思念章达走入相邻书房，然后从这处私密空间拨出关键电话。电话另一端出现争执和旁人的声音，学生却只知道他进入书房，没有看到他正常离开；后来破门时房间已经无人。国际警方据时间记录与现场条件调查，提出被人从窗口胁持的可能，却未能找到本人。卫斯理一度假定他已遇害，正文没有给出尸体或明确结论，所以本卡保留失踪而不把推断写成死亡。李逊的价值在于坚持把异常行为作为可以合作研究的对象，并愿意在同伴死后寻找外部帮助。终局演绎可让他更重视联络冗余与证据保全，却不能自动获得外星人的通讯、读心或研究对手的完整知识。他的缺席也是原案的重要限制：任何关于他最后见到什么、遭到何种处理的细节，都必须保持未知。',
'在与卫斯理通话的书房内失踪；后续生死不明。','联合研究与跨地联络','参与人性与生理变化因素的合作研究，借电话向可信调查者提供疑问。','没有明确战斗或超常能力；长途联络中断，研究材料和现场保护不足。失踪不等于能自主隐身或瞬移。',[(327,350,'联合报告和来电'),(430,465,'电话、书房与失踪调查'),(1214,1218,'卫的死亡假定并非确证')],
'延续共同研究并使异常压力得到外界关注。',[('合作伙伴突然遇害','已有未完成的共同成果','联系可信调查者并保存可核实的工作线索。'),('安全联络出现第三者干扰','无法保证继续通话','尽量说明现场变化，不把无证据的解释当答案。'),('有人要求他确认自己不知道的内幕','缺少亲历证据','区分研究假设与目击内容，承认空白。')],scores=(1,0,1,2,1,1),tier='并',deploy='采用失踪前最后可自主研究与联络的形态；后续未知，不补造囚禁、死亡或逃脱细节。')
make('ding_amao','丁阿毛',B,
'丁阿毛是一名十六岁半的惯常违法少年，档案从十二岁开始记录侵害、抢劫和反复进入管教机构，也包括逃出管教的经历。他与卫斯理的冲突起初像街头暴力，随后却成为一场蓄意谋杀的掩护。有人给他金钱承诺，要求他先恨上一个人，再到那人家中杀死另一个人，装成失手；同伴回忆他为即将有钱而兴奋，又对接头者感到害怕。他在拘押中伤害人员、夺取枪械逃走，最终开枪杀害章达，被卫斯理再次制住。此后他在拘留所自杀，截断了直接追查幕后人的途径。原作把这些行动与外来脑电波控制联系起来，却没有逐次标定他哪些旧罪完全出于自主、哪些步骤受到了控制，因此不能以一个笼统标签取消全部责任，也不能把他写成没有受操纵风险的纯粹自由凶手。普通刀枪已足以让他对无防备者造成致命伤害，但近身时他不敌卫斯理，没有技巧无限增长的根据。终局后演绎应使金钱诱惑、受制恐惧、冲动报复和被利用的意识发生冲突，避免仅重复骂人和攻击的单一反应。',
'枪杀章达后被拘捕，随后在拘留所自杀。','街头暴力与有预谋枪击','使用普通刀枪，利用既有冲突制造谋杀看似误杀的表象。','无超常身体；近身被卫斯理制伏。外来指使或控制会剥夺自主性，不能把幕后技术算成本人能力。',[(168,174,'越押、伤人和夺枪'),(224,250,'枪击与被制伏'),(534,540,'拘留所自杀'),(603,609,'年龄及案底'),(930,949,'金钱与谋杀安排')],
'追逐眼前的金钱和面子，又害怕掌握自己的幕后力量。',[('有人以钱指使伤害','报酬大而要求隐瞒','容易被诱惑，同时会试探对方是否会灭口。'),('受到当众压制','有武器且情绪激烈','倾向冲动升级，真实武力差距仍会使他失败。'),('发现行动并非自己能决定','出现无法解释的命令冲动','尝试向可信第三方暴露联系，不能凭意志宣称免疫。')],roles=('反派','被操纵的主线人物'),dead=True,scores=(2,0,1,2,2,2),tier='并',limits=(3,1,2))
make('a_zhong','阿中',B,
'阿中是贫困街区的青年，卫斯理在狭窄楼梯让他让路时，他突然拔刀攻击，随即被踢下楼梯。这个明确的敌对行为使他不能只被写成温和带路人，但原文后来也给出与最初印象不同的一面。阿玲请他带卫斯理去找丁阿毛的同伴，他尽管刚与来客打过架，仍因为喜欢阿玲而答应，并在叮嘱送到就回时露出短暂快乐。他想娶阿玲，却难以开口表达；得知她遭受那些人的侵害和后续处境，他曾去打人，结果坐了三个月牢。他把悲痛和愤怒留在紧握的双手与断续叙述里，到达铁皮屋附近后，指明位置便奔离，没有陪卫斯理完成审问。他所知道的是街区关系与具体地点，不是外星操纵的全貌。这个人物的逻辑由暴躁的防卫、低下的处境和对某人的深情交织而成，不能把喜欢阿玲写成拥有或替她决定人生的权利。终局形态仍是普通青年；综合经历可以让他在再次被请求带路时谨慎检查危险，也可以令他学习用言语说明怒意，但没有突然成为专业侦探或高手的依据。',
'带卫斯理找到同伴聚处后离开，后续未交代。','街区信息与有限刀械反击','熟悉丁阿毛同伴聚会地点，可带路；曾拔刀攻击并因冲突入狱。','普通人体、武技有限；情绪容易使行动失控，不能凭喜欢某人获得对方服从。',[(819,848,'身份、先前袭击与接受带路'),(859,881,'情感、入狱及指路离开')],
'保护自己重视的人，寻找从暴力循环中脱身的办法。',[('陌生人逼近或命令他','感到受辱且缺少退路','先出现攻击冲动，终局经历使他可能选择拉开距离。'),('阿玲提出具体帮助请求','请求不要求继续侵害别人','愿意承担带路风险并遵守约定。'),('追忆曾受的羞辱和失败','身体情绪开始失控','用明确事实表达痛苦，避免把愤怒转嫁给弱者。')],roles=('阶段性对立者',),scores=(2,0,0,2,1,2),tier='并')
make('ding_gang','丁阿毛的铁皮屋同伙',B,
'这群未逐一留下姓名的男女在狭窄街巷的铁皮屋聚会，是丁阿毛日常往来的同伴，也是调查者取得谋杀安排线索的关键场所。他们的群体身份由阿玲和阿中的叙述，以及卫斯理实际走入屋内的遭遇相互锚定，不可扩写成一个跨城犯罪组织。其中有人抓住卫斯理的衣领挑衅，旁人起哄，直到那人被重手法弄伤颈部，其他人才因恐惧后退。随后他们逐项回答问题：丁阿毛曾夸耀将得到大笔钱，有时兴奋有时害怕；一个同行者远远看见他与乘豪华汽车、穿西装的两人接头，还听他解释制造仇恨与假装误杀的任务。这样的证词支持他们知道外围事实，却不证明他们共同参与每一项谋杀步骤，更不能把外星控制者的技术交给整个群体。阿中的叙述还把聚处与阿玲受侵害的经历相连，这构成其反派功能，处理时应只记责任关系，不以露骨细节增强所谓凶恶。终局没有集体被捕或死亡的交代。参战可以保留人数、地头熟悉和互相壮胆的行为，但群体在强势反制前会迅速动摇，每个不具名成员也不应凭群体卡自动拥有全部罪行与知识。',
'遭卫斯理压制并提供丁阿毛接头线索；后续未交代。','群体威吓与街区情报','凭人数、熟悉地形和日常往来形成局部压力，掌握有限的接头见闻。','本卡仅限同一铁皮屋群体；不能自动调动全城同伙。遭实际反制会退缩，个人目击并非全员全知。',[(859,881,'与阿玲经历关联的聚处'),(910,949,'挑衅、受制及供出谋杀安排')],
'维持小圈子的面子和利益，受威胁时优先保全自己。',[('有陌生人进入聚处','人数优势令其自信','以嘲弄、围拢试探对方，不等于必能获胜。'),('同伴被迅速制住','己方无法承受实际伤害','后退并选择交代所知来解除压力。'),('有人追问幕后','只有部分成员亲历接头','分别说明谁看见什么，不虚构整套计划。')],roles=('反派群体',),scores=(2,0,1,2,1,2),tier='并')
make('jintou_asia_pair','尽头事件的亚洲联络二人组',B,
'这两名没有姓名的亚洲联络者原先是无线电爱好者，自建接收站并与各地同好通联。他们逐渐获得书本上没有的知识，改进设备、制造零件和新的半导体，直到一年后直接接到太空站通讯，才知道那些灵感来自外部灌入。他们由此承担地面任务，获得受控制者送来的钱和奢华生活，也失去真正脱离的自由。二人参与接触丁阿毛，后来探看装作失忆的卫斯理；当远方通知指出失忆是伪装，他们取出灭声手枪，准备再次杀人。信息传送需要时间，使卫斯理能够利用空当潜入住宅并与白素伏击他们。一人被击昏，另一人在枪口下说明控制机制、联络距离和自身恐惧，承认上级可以迫使他们自杀。原作最后报道他们的住宅爆炸，卫斯理推断是泄密受罚，没有现场确认两具尸体。综合卡应保留这种终局危局与受害、加害并存的处境，不把他们说成只是无辜信使，也不让他们自主掌握母体的全球读心权。所谓亚洲仅有二人是其口供，不能进一步补出未出现的世界代理名册。',
'被卫白制伏并泄露通讯秘密，三天后住宅爆炸，个体生死未直接确认。','外来指导的无线电技术与地面执行','两人操作固定接收台、制造获指导零件，凭命令和普通枪械执行监视与谋杀。','认知消息依赖远程通讯并有延迟；自己也可受上级控制。无独立读心，近身不敌卫白；爆炸后设备可用性未证实。',[(1503,1532,'装置及接收干扰'),(1553,1588,'得知伪失忆后谋杀行动'),(1623,1696,'被制伏、受控制与技术来源'),(1719,1728,'利益与老蔡偷换报告'),(1780,1783,'住宅爆炸及推断')],
'在服从、利益和对远方惩罚的恐惧之间求生。',[('收到新的行动命令','通讯可用且内容明确','按有限信息准备执行，同时顾虑被牺牲。'),('掌控者迟迟未回报','信息存在传送时间','只能用本地观察填空，不能装作实时全知。'),('被揭穿且性命受威胁','对方提供暂时生路','倾向泄露所知，但会恐惧上级的后续惩罚。')],roles=('反派群体','受控制的地面代理'),scores=(2,1,2,2,3,3),tier='强',limits=(3,3,1),uncertainties=('住宅爆炸可确认，二人死亡为卫斯理推断，未见尸体。',))
make('jintou_controllers','尽头事件的太空站控制者',B,
'这批未现身、未具姓名的外来控制者只通过地面接收装置、代理人的口供和已发生的操纵结果进入故事。其太空站被描述为位于地日距离一百三十倍处的球状设施，真实母星更远，身份和社会结构无人知晓。他们给两名无线电爱好者注入技术知识，使其逐步造出可通讯的设备，再用物质享受与可致命的控制维持代理关系。地面证据显示他们能识别卫斯理假装失忆，也能借可控制者偷换研究报告；但对不同人的能力不同，有些只能被探测思想，尚不能被命令行动，老蔡的可控状态也不稳定。他们针对发现异常的学者，通过代理与既有社会冲突把谋杀伪装成偶然，目的是使地球科技停止发展，从而不发现他们。这并非原作已经实现的人类末日，结尾主要是卫斯理和白素对长期前景的恐惧。控制者也不是即时全知：通信距离产生明显延迟，地面代理因此会被欺骗、伏击和逼供。角色化时应保持其隐蔽、间接和预防竞争者成长的逻辑，不能把小说中的政治社会议论全部解释为本卡已验证的具体操纵，更不能据无现身推定身体无敌或拥有毁灭宇宙的武器。',
'太空站与控制机制未被消除，地面联络住宅爆炸；长期计划最终成败未写出。','条件性脑电波探测、控制与知识传入','依太空站技术远距探测思想，只能控制部分相容目标；可注入技术并通过地面代理间接破坏研究。','探测不等于能控制所有对象；联络存在长距离延迟，具体身体、武器与正面抗性未知。不能把代理资源全部当个人装备。',[(1553,1579,'探知伪失忆与时间延迟'),(1653,1661,'可控和不可控两类'),(1686,1728,'知识输入、太空站和控制老蔡'),(1755,1758,'阻止被地球发现的目的'),(1780,1799,'爆炸与尚未实现的长期末日')],
'隐蔽阻断可能发现自身的文明发展，以代理制造看似内部的破坏。',[('研究者逼近控制机制','直接控制其本人失败','动用地面代理干扰证据和安排袭击。'),('目标不属于可控类型','只能读取而不能命令','寻找可控中介，不能临时升级为绝对支配。'),('地面情报失去实时性','通信延迟形成空窗','接受代理可能失败的风险，重新核验而非凭空补知。')],roles=('幕后反派群体',),scores=(0,7,8,8,9,3),tier='准神',limits=(3,6,1),destruction='没有直接物理毁灭表现；主要以控制、代理和社会破坏间接造成伤亡。',durability='本体未现，身体耐久未知；不能由太空站存在推定个体无敌。',speed='本体移动未示，信息传送受远距时间约束。',energy='太空站提供远距离精神信息作用，缺乏可量化炮击输出。',stamina='依赖外部太空站与长期网络运行，非个体无限续航。',intelligence={'in_combat':'擅长代理与掩护，地面交战可被信息时差击败。','knowledge':'具远距精神信息及先进通信技术。','planning':'以地球人的既有冲突掩盖定点清除和发展阻断。','adaptation':'能更新命令，但需等待通信，控制对象相容性是硬限制。'},confidence='medium')
